svg.script:
//!export-start
var _pn_value = 50;
var _ps_label = 'Label';
var _pc_color = '#3366cc';
//!export-end

function putValue(id, value) {
  if (id === '_pn_value') {
    document.getElementById('value').textContent = 'Value: ' + value;
  } else if (id === '_ps_label') {
    document.getElementById('label').textContent = value;
  } else if (id === '_pc_color') {
    document.getElementById('iconBg').setAttribute('fill', value);
  }
}

document.getElementById('icon').addEventListener('click', function () {
  _pn_value = _pn_value + 1;
  document.getElementById('value').textContent = 'Value: ' + _pn_value;
  postValue('_pn_value', _pn_value);
});
